type TopicSeed = Omit<Topic, 'concepts'> & { concepts: [string, string, string][] };

function seededTopic(seed: TopicSeed): Topic {
  return {
    ...seed,
    concepts: seed.concepts.map(([name, principle, example]) => ({
      name,
      principle,
      example,
      decision: `В артефакте «${seed.deliverable}» явно зафиксировать ${name.toLocaleLowerCase('ru')} и связать с источником.`,
      pitfall: `Оставить «${name}» неявным и обнаружить разночтение только во время реализации`,
      check: `Для аспекта «${name}» указаны источник, ответственная роль и проверяемый критерий`,
    })),
  };
}

